<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Terra Moss — Store</title><link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600&family=DM+Sans:wght@300;400;500&display=swap" rel="stylesheet"><style>
:root{--gd:#1a3a2a;--gm:#2d5a3d;--gl:#4a8c5c;--gp:#a8d5b5;--gmist:#e8f5ec;--earth:#8b6914;--cream:#faf8f3;--tx:#1c2b22;--txm:#5a7060;--w:#fff;--br:rgba(45,90,61,.15);--sh:0 4px 24px rgba(26,58,42,.1)}*{margin:0;padding:0;box-sizing:border-box}html{scroll-behavior:smooth}body{font-family:'DM Sans',sans-serif;background:var(--cream);color:var(--tx)}nav{position:fixed;top:0;left:0;right:0;z-index:20;background:rgba(26,58,42,.97);height:68px;padding:0 5%;display:flex;align-items:center;justify-content:space-between}.logo{font-family:'Playfair Display',serif;font-size:1.5rem;color:var(--gp);text-decoration:none}.logo span{color:#c4a95a;font-style:italic}.links{display:flex;gap:1.4rem;list-style:none}.links a{color:rgba(168,213,181,.85);text-decoration:none;font-size:.9rem}.mobile-cat{display:none;background:rgba(255,255,255,.95);color:var(--gd);border:1px solid rgba(168,213,181,.35);border-radius:18px;padding:8px 10px;font-family:inherit;max-width:132px}.home-float{position:fixed;left:16px;bottom:18px;z-index:35;background:var(--gd);color:#fff;text-decoration:none;border-radius:22px;padding:10px 15px;box-shadow:var(--sh);font-size:.88rem}.cart-btn,.btn{background:var(--earth);color:white;border:0;border-radius:24px;padding:10px 18px;cursor:pointer;font-family:inherit}.btn{background:var(--gl);padding:12px 24px;text-decoration:none;display:inline-block}.cart-count{background:var(--gp);color:var(--gd);border-radius:50%;padding:2px 7px;margin-left:5px}section{padding:90px 5%}.hero{min-height:100vh;background:linear-gradient(135deg,var(--gd),#0d2218);display:flex;align-items:center;padding-top:120px}.hero h1{font-family:'Playfair Display',serif;color:white;font-size:clamp(2.4rem,5vw,4rem);line-height:1.15;max-width:700px}.hero h1 em{color:var(--gp)}.hero p{color:rgba(168,213,181,.75);max-width:520px;line-height:1.7;margin:18px 0 28px}.section-head{text-align:center;margin-bottom:35px}.tag{color:var(--gl);font-size:.78rem;letter-spacing:.14em;text-transform:uppercase}.section-head h2{font-family:'Playfair Display',serif;color:var(--gd);font-size:clamp(1.8rem,3vw,2.5rem)}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:1.5rem;max-width:1200px;margin:auto}.card{background:white;border:1px solid var(--br);border-radius:14px;overflow:hidden;box-shadow:var(--sh);cursor:pointer;display:flex;flex-direction:column}.pimg{height:190px;background:var(--gmist);display:flex;align-items:center;justify-content:center;font-size:4rem;position:relative;overflow:hidden}.pimg img{width:100%;height:100%;object-fit:cover;position:absolute}.badge{position:absolute;top:10px;left:10px;background:var(--gd);color:var(--gp);padding:3px 10px;border-radius:12px;font-size:.7rem;z-index:2}.info{padding:1rem;display:flex;flex-direction:column;flex:1}.name{font-weight:600;color:var(--gd)}.desc{font-size:.86rem;color:var(--txm);line-height:1.5;margin-top:5px;flex:1}.pay{display:inline-block;font-size:.72rem;padding:3px 9px;border-radius:12px;margin-top:.7rem}.cod{background:#d4edda;color:#155724}.fifty{background:#ffe8f0;color:#c2185b}.foot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--br);margin-top:1rem;padding-top:.8rem}.price{font-family:'Playfair Display',serif;color:var(--gd);font-size:1.2rem;font-weight:600}.add{background:var(--gm);color:white;border:0;border-radius:18px;padding:8px 14px;cursor:pointer}.overlay{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:40;display:none;align-items:center;justify-content:center;padding:1rem}.overlay.open{display:flex}.modal{background:white;border-radius:18px;width:min(850px,96vw);max-height:92vh;overflow:auto}.pd{display:grid;grid-template-columns:1fr 1fr}.pd-gallery{background:var(--gmist);display:flex;flex-direction:column;overflow:hidden}.pd-main{aspect-ratio:1;background:var(--gmist);display:flex;align-items:center;justify-content:center;font-size:5rem;overflow:hidden;position:relative}.pd-main img{width:100%;height:100%;object-fit:cover}.pd-fallback{width:100%;height:100%;align-items:center;justify-content:center}.pd-arrow{position:absolute;top:50%;transform:translateY(-50%);z-index:5;width:38px;height:38px;border:0;border-radius:50%;background:rgba(255,255,255,.9);color:var(--gd);font-size:1.8rem;line-height:1;cursor:pointer;box-shadow:0 2px 12px rgba(0,0,0,.18)}.pd-arrow.left{left:12px}.pd-arrow.right{right:12px}.pd-counter{position:absolute;right:12px;bottom:12px;z-index:5;background:rgba(26,58,42,.82);color:#fff;border-radius:16px;padding:4px 10px;font-size:.78rem}.pd-thumbs{display:flex;gap:.5rem;padding:.75rem;background:#fff;overflow-x:auto;border-top:1px solid var(--br)}.pd-thumb{width:64px;height:64px;flex:0 0 auto;border:2px solid transparent;border-radius:10px;overflow:hidden;background:var(--gmist);cursor:pointer;padding:0}.pd-thumb.active{border-color:var(--gl)}.pd-thumb img{width:100%;height:100%;object-fit:cover;display:block}.pd-info{padding:2rem}.close{float:right;background:none;border:0;font-size:1.5rem;cursor:pointer}.cart-panel{position:fixed;right:0;top:0;bottom:0;width:min(420px,96vw);background:white;z-index:45;transform:translateX(105%);transition:.3s;box-shadow:-8px 0 30px rgba(0,0,0,.15);display:flex;flex-direction:column}.cart-panel.open{transform:none}.cart-head,.cart-foot{padding:1rem 1.4rem;border-bottom:1px solid var(--br);display:flex;justify-content:space-between}.cart-foot{border-top:1px solid var(--br);border-bottom:0;display:block}.cart-items{flex:1;overflow:auto;padding:1rem}.cart-item{display:flex;gap:.8rem;border-bottom:1px solid var(--br);padding:.8rem 0}.ci-img{width:55px;height:55px;border-radius:8px;background:var(--gmist);overflow:hidden;display:flex;align-items:center;justify-content:center}.ci-img img{width:100%;height:100%;object-fit:cover}.form{padding:1.5rem}.fg{margin-bottom:1rem}.fg label{display:block;font-size:.82rem;color:var(--txm);margin-bottom:5px}.fg input,.fg textarea,.fg select{width:100%;padding:11px;border:1px solid var(--br);border-radius:8px;font-family:inherit;background:#fff}.row{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.toast{position:fixed;bottom:2rem;left:50%;transform:translateX(-50%) translateY(100px);background:var(--gd);color:white;padding:12px 22px;border-radius:30px;z-index:99;transition:.3s}.toast.show{transform:translateX(-50%) translateY(0)}footer{background:#0d1f16;color:rgba(168,213,181,.55);padding:2rem 5%;text-align:center}@media(max-width:768px){
.links{display:none}
.mobile-cat{display:block}
nav{padding:0 3%;gap:.45rem}
.logo{font-size:1.15rem;white-space:nowrap}
.cart-btn{padding:9px 11px;font-size:.84rem}
.home-float{left:12px;bottom:12px;padding:9px 12px;font-size:.82rem}
.row{grid-template-columns:1fr}
.hero{min-height:80vh}
.overlay{align-items:flex-start;justify-content:center;padding:12px;overflow-y:auto}
.modal{width:100%;max-height:none;overflow:visible;border-radius:16px;margin:10px 0 30px}
.pd{display:block;grid-template-columns:1fr;position:relative;overflow:hidden}
.pd-gallery{border-radius:16px 16px 0 0;overflow:hidden}
.pd-main{width:100%;aspect-ratio:4/3;max-height:320px;border-radius:16px 16px 0 0;position:relative;z-index:1}
.pd-main img{width:100%;height:100%;object-fit:cover;display:block}
.pd-thumbs{padding:.55rem;gap:.4rem}
.pd-thumb{width:56px;height:56px}
.pd-arrow{width:34px;height:34px;font-size:1.55rem}
.pd-info{position:relative;z-index:2;background:var(--w);padding:1.2rem 1rem 1.4rem;border-radius:0 0 16px 16px;clear:both}
.pd-info h2{font-size:1.35rem;line-height:1.25;margin-top:.4rem;color:var(--gd)}
.pd-info h3{font-size:1.15rem;line-height:1.3;margin:.35rem 0;color:var(--earth)}
.pd-info .tag{display:block;margin-top:.2rem;padding-right:46px}
.close{float:none;position:absolute;top:10px;right:10px;z-index:20;background:#fff;border-radius:50%;width:38px;height:38px;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 12px rgba(0,0,0,.22);font-size:1.6rem;line-height:1}
#pdOverlay .close{position:absolute;top:10px;right:10px}
#pdDesc,#pdFeatures,#pdPay,#pdName,#pdPrice{position:relative;z-index:3;background:var(--w)}
}
</style></head><body><div id="toast" class="toast"></div><nav><a class="logo" href="#home" onclick="goHome()">Terra <span>Moss</span></a><ul class="links"><li><a href="#home">Home</a></li><li><a href="#plants">Plants</a></li><li><a href="#terrariums">Terrariums</a></li><li><a href="#paludariums">Paludariums</a></li><li><a href="#other">More</a></li><li><a href="#contact">Contact</a></li></ul><select class="mobile-cat" aria-label="Choose category" onchange="jumpCategory(this.value);this.value=''"><option value="">Category</option><option value="home">Home</option><option value="plants">Plants</option><option value="terrariums">Terrariums</option><option value="paludariums">Paludariums</option><option value="other">More</option><option value="contact">Contact</option></select><button class="cart-btn" onclick="toggleCart()">🛒 Cart <span class="cart-count" id="cartCount">0</span></button></nav><a class="home-float" href="#home" onclick="goHome()">⌂ Home</a>
<section class="hero" id="home"><div><div class="tag" style="color:var(--gp)">Premium Nature Enclosures</div><h1 id="heroTitle">Bring Nature <em>Indoors</em> with Us</h1><p id="heroSub">Handcrafted terrariums, paludariums, and rare tropical plants — curated for enthusiasts who believe living art belongs in every space.</p><a class="btn" href="#terrariums">Shop Terrariums</a></div></section>
<section id="about" style="background:white"><div class="section-head"><div class="tag">Who We Are</div><h2>Passionate About Living Ecosystems</h2><p id="aboutT1" style="max-width:760px;margin:1rem auto;color:var(--txm);line-height:1.7">TerraMoss was born from a deep love for miniature ecosystems.</p><p id="aboutT2" style="max-width:760px;margin:auto;color:var(--txm);line-height:1.7">Based in Bangladesh, we craft and curate terrariums, paludariums, and rare tropical plants.</p></div></section>
<section id="plants"><div class="section-head"><div class="tag">Plants</div><h2>Terrarium Plants</h2></div><div class="grid" id="plantsGrid"></div></section>
<section id="terrariums" style="background:white"><div class="section-head"><div class="tag">Terrariums</div><h2>Complete Terrariums</h2></div><div class="grid" id="terrariumsGrid"></div></section>
<section id="paludariums"><div class="section-head"><div class="tag">Paludariums</div><h2>Aquatic Paludariums</h2></div><div class="grid" id="paludariumsGrid"></div></section>
<section id="other" style="background:white"><div class="section-head"><div class="tag">More</div><h2>Other Products</h2></div><div class="grid" id="otherGrid"></div></section>
<section id="contact"><div class="section-head"><div class="tag">Contact</div><h2>Contact Us</h2><p id="cPhone">📱 +880 1XXXXXXXXX</p><p id="cEmail">📧 hello@terraverde.com.bd</p><p id="cAddr">📍 Dhaka, Bangladesh</p></div></section><footer>© 2026 Terra Moss. All rights reserved.</footer>
<div class="overlay" id="pdOverlay"><div class="modal pd"><div class="pd-gallery"><div class="pd-main" id="pdImg"></div><div class="pd-thumbs" id="pdThumbs"></div></div><div class="pd-info"><button class="close" onclick="closePD()">×</button><div class="tag" id="pdBadge"></div><h2 id="pdName"></h2><h3 id="pdPrice"></h3><div id="pdPay"></div><p id="pdDesc" style="color:var(--txm);line-height:1.7;margin:1rem 0"></p><ul id="pdFeatures" style="margin-left:1.2rem;color:var(--txm);line-height:1.8"></ul><button class="btn" id="pdAdd">🛒 Add to Cart</button></div></div></div>
<div class="cart-panel" id="cartPanel"><div class="cart-head"><h3>Your Cart</h3><button class="close" onclick="toggleCart()">×</button></div><div class="cart-items" id="cartItems"></div><div class="cart-foot"><h3>Total: <span id="cartTotal">৳0</span></h3><button class="btn" style="width:100%;margin-top:1rem" onclick="openCheckout()">Proceed to Checkout</button></div></div>
<div class="overlay" id="checkoutOverlay"><div class="modal form"><button class="close" onclick="closeCheckout()">×</button><h2>Complete Your Order</h2><div id="orderSummary" style="background:var(--gmist);padding:1rem;border-radius:10px;margin:1rem 0"></div><div class="row"><div class="fg"><label>Full Name *</label><input id="cName"></div><div class="fg"><label>Phone *</label><input id="coPhone"></div></div><div class="fg"><label>Delivery Address *</label><textarea id="coAddr"></textarea></div><div class="row"><div class="fg"><label>Delivery Area *</label><select id="deliveryArea" onchange="selectedDelivery=this.value;refreshCheckoutSummary()"><option value="inside_dhaka">Inside Dhaka — ৳80</option><option value="outside_dhaka">Outside Dhaka — ৳150 terrariums / ৳130 plants</option></select></div><div class="fg"><label>District</label><input id="cDistrict" oninput="autoDetectDhaka()"></div></div><div class="fg"><label>Note</label><input id="cNote"></div><div id="paymentBox"></div><button class="btn" style="width:100%;margin-top:1rem" onclick="placeOrder()">✅ Place Order</button></div></div>
<script>
let products={plants:[],terrariums:[],paludariums:[],other:[]},cart=[],selectedPay='cod',selectedDelivery='inside_dhaka',pdProduct=null,pdImages=[],pdIndex=0,pdTouchX=0;
const $=id=>document.getElementById(id);function toast(m){$('toast').textContent=m;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}
async function api(action,data=null){const opt=data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{};const r=await fetch('api.php?action='+action,opt);return r.json();}
function allP(){return [...products.plants,...products.terrariums,...products.paludariums,...products.other]}function findP(id){return allP().find(p=>p.id===id)}
function payBdg(p){return p==='fifty'?'<span class="pay fifty">📱 50% Advance</span>':'<span class="pay cod">✅ Cash on Delivery</span>'}
function goHome(){closePD();closeCheckout();$('cartPanel').classList.remove('open')}function jumpCategory(id){if(!id)return;goHome();location.hash=id}
function cartSubtotal(){return cart.reduce((a,i)=>a+Number(i.price)*Number(i.qty),0)}function deliveryCharge(area=selectedDelivery){if(area==='inside_dhaka')return 80;return cart.some(i=>['terrariums','paludariums'].includes(i.category))?150:130}function deliveryLabel(){return selectedDelivery==='inside_dhaka'?'Inside Dhaka':'Outside Dhaka'}function autoDetectDhaka(){let d=($('cDistrict')?.value||'').trim().toLowerCase();if(d==='dhaka'||d==='ঢাকা'){selectedDelivery='inside_dhaka';$('deliveryArea').value='inside_dhaka';refreshCheckoutSummary()}}
function imgHtml(p){return p.images&&p.images.length?`<img src="${p.images[0]}" onerror="this.remove()"><span>${p.emoji||'🌿'}</span>`:`<span>${p.emoji||'🌿'}</span>`}
function card(p){return `<div class="card" onclick="openPD('${p.id}')"><div class="pimg"><span class="badge">${p.badge||''}</span>${imgHtml(p)}</div><div class="info"><div class="name">${p.name}</div><div class="desc">${p.desc||''}</div>${payBdg(p.paymentPolicy)}<div class="foot"><div class="price">৳${Number(p.price).toLocaleString()}</div><button class="add" onclick="event.stopPropagation();addToCart('${p.id}')">+ Add</button></div></div></div>`}
function render(){['plants','terrariums','paludariums','other'].forEach(c=>$(c+'Grid').innerHTML=(products[c]||[]).map(card).join('')||'<p>No products yet.</p>')}
async function load(){let p=await api('products');if(p.ok){products=p.products;render()}let c=await api('content');if(c.ok){let x=c.content;if(x.heroTitle)$('heroTitle').textContent=x.heroTitle;if(x.heroSub)$('heroSub').textContent=x.heroSub;if(x.about1)$('aboutT1').textContent=x.about1;if(x.about2)$('aboutT2').textContent=x.about2;if(x.phone)$('cPhone').textContent='📱 '+x.phone;if(x.email)$('cEmail').textContent='📧 '+x.email;if(x.address)$('cAddr').textContent='📍 '+x.address}}
function escAttr(s){return String(s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function renderPDGallery(){let p=pdProduct;if(!p)return;let has=pdImages.length>0,src=has?pdImages[pdIndex]:'';let fallback=`<span class="pd-fallback" style="display:${has?'none':'flex'}">${p.emoji||'🌿'}</span>`;let arrows=pdImages.length>1?`<button type="button" class="pd-arrow left" onclick="event.stopPropagation();changePDImage(-1)">‹</button><button type="button" class="pd-arrow right" onclick="event.stopPropagation();changePDImage(1)">›</button><div class="pd-counter">${pdIndex+1}/${pdImages.length}</div>`:'';$('pdImg').innerHTML=has?`<img src="${escAttr(src)}" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'">${fallback}${arrows}`:fallback;$('pdThumbs').innerHTML=pdImages.length>1?pdImages.map((u,i)=>`<button type="button" class="pd-thumb ${i===pdIndex?'active':''}" onclick="changePDImageTo(${i})"><img src="${escAttr(u)}" onerror="this.style.display='none'"></button>`).join(''):''}
function changePDImage(step){if(pdImages.length<2)return;pdIndex=(pdIndex+step+pdImages.length)%pdImages.length;renderPDGallery()}function changePDImageTo(i){pdIndex=i;renderPDGallery()}
function openPD(id){let p=findP(id);if(!p)return;pdProduct=p;pdImages=Array.isArray(p.images)?p.images.filter(Boolean):[];pdIndex=0;renderPDGallery();$('pdImg').ontouchstart=e=>{pdTouchX=e.changedTouches[0].screenX};$('pdImg').ontouchend=e=>{let dx=e.changedTouches[0].screenX-pdTouchX;if(Math.abs(dx)>45)changePDImage(dx<0?1:-1)};$('pdBadge').textContent=p.badge||'';$('pdName').textContent=p.name;$('pdPrice').textContent='৳'+Number(p.price).toLocaleString()+' BDT';$('pdPay').innerHTML=payBdg(p.paymentPolicy);$('pdDesc').textContent=p.fullDesc||p.desc||'';$('pdFeatures').innerHTML=(p.features||[]).map(f=>`<li>${f}</li>`).join('');$('pdAdd').onclick=()=>addToCart(id);$('pdOverlay').classList.add('open')}function closePD(){$('pdOverlay').classList.remove('open')}
function addToCart(id){let p=findP(id);let x=cart.find(i=>i.id===id);if(x)x.qty++;else cart.push({...p,qty:1});updateCart();toast(p.name+' added')}
function updateCart(){$('cartCount').textContent=cart.reduce((a,i)=>a+i.qty,0);$('cartTotal').textContent='৳'+cartSubtotal().toLocaleString();$('cartItems').innerHTML=cart.length?cart.map(i=>`<div class="cart-item"><div class="ci-img">${i.images&&i.images[0]?`<img src="${i.images[0]}">`:i.emoji}</div><div style="flex:1"><b>${i.name}</b><br>৳${Number(i.price).toLocaleString()} × ${i.qty}<br><button onclick="chgQty('${i.id}',-1)">−</button> <button onclick="chgQty('${i.id}',1)">+</button> <button onclick="rmItem('${i.id}')">Remove</button></div></div>`).join(''):'<p>Your cart is empty.</p>'}
function chgQty(id,d){let x=cart.find(i=>i.id===id);if(!x)return;x.qty+=d;if(x.qty<=0)cart=cart.filter(i=>i.id!==id);updateCart()}function rmItem(id){cart=cart.filter(i=>i.id!==id);updateCart()}function toggleCart(){$('cartPanel').classList.toggle('open')}
function refreshCheckoutSummary(){if(!$('orderSummary'))return;let subtotal=cartSubtotal(),delivery=deliveryCharge(),grand=subtotal+delivery,adv=Math.ceil(grand*.5);$('orderSummary').innerHTML=cart.map(i=>`<div>${i.name} × ${i.qty} <b style="float:right">৳${(i.price*i.qty).toLocaleString()}</b></div>`).join('')+`<hr><div>Subtotal <b style="float:right">৳${subtotal.toLocaleString()}</b></div><div>Delivery (${deliveryLabel()}) <b style="float:right">৳${delivery.toLocaleString()}</b></div><hr><b>Total: ৳${grand.toLocaleString()}</b>`;let advNote=$('advanceNote');if(advNote)advNote.textContent='50% Bkash advance required. Amount: ৳'+adv.toLocaleString()}
function openCheckout(){if(!cart.length)return toast('Cart is empty');$('cartPanel').classList.remove('open');selectedDelivery='inside_dhaka';if($('deliveryArea'))$('deliveryArea').value=selectedDelivery;let need=cart.some(i=>i.paymentPolicy==='fifty');selectedPay=need?'fifty':'cod';$('paymentBox').innerHTML=need?`<p class="pay fifty" id="advanceNote"></p><div class="fg"><label>Bkash Number *</label><input id="bkFrom"></div><div class="fg"><label>Transaction ID *</label><input id="bkTrx"></div>`:`<label><input type="radio" name="pay" checked onchange="selectedPay='cod';document.getElementById('bkFields').style.display='none'"> Cash on Delivery</label><br><label><input type="radio" name="pay" onchange="selectedPay='bkash';document.getElementById('bkFields').style.display='block'"> 50% Bkash Advance</label><div id="bkFields" style="display:none;margin-top:1rem"><div class="fg"><label>Bkash Number *</label><input id="bkFrom"></div><div class="fg"><label>Transaction ID *</label><input id="bkTrx"></div></div>`;$('checkoutOverlay').classList.add('open');refreshCheckoutSummary()}function closeCheckout(){$('checkoutOverlay').classList.remove('open')}
async function placeOrder(){let name=$('cName').value.trim(),phone=$('coPhone').value.trim(),address=$('coAddr').value.trim();if(!name||!phone||!address)return toast('Please fill required fields');if(selectedPay!=='cod'&&(!($('bkFrom')?.value.trim())||!($('bkTrx')?.value.trim())))return toast('Please fill Bkash details');let data={name,phone,address,district:$('cDistrict').value,note:$('cNote').value,deliveryArea:selectedDelivery,payment:selectedPay,payLabel:selectedPay==='cod'?'Cash on Delivery':'50% Bkash Advance',bkashFrom:$('bkFrom')?.value||'',bkashTrx:$('bkTrx')?.value||'',items:cart.map(i=>({id:i.id,qty:i.qty}))};let res=await api('create_order',data);if(res.ok){toast('Order placed! ID: '+res.id+' | Total: ৳'+Number(res.total).toLocaleString());cart=[];updateCart();closeCheckout()}else toast(res.error||'Order failed')}
load();
</script></body></html>
